// 桐城自摸麻将 - 局域网服务器
// 运行方式: node majiang-server.js

const http = require('http');
const fs = require('fs');
const path = require('path');
const WebSocket = require('ws');

const PORT = 8082;

// ==================== HTTP服务器 ====================
const server = http.createServer((req, res) => {
    console.log(`HTTP请求: ${req.url}`);

    if (req.url === '/' || req.url === '/index.html') {
        const htmlPath = path.join(__dirname, 'majiang-lan.html');
        fs.readFile(htmlPath, (err, data) => {
            if (err) {
                res.writeHead(404);
                res.end('游戏文件未找到');
                return;
            }
            res.writeHead(200, {
                'Content-Type': 'text/html; charset=utf-8'
            });
            res.end(data);
        });
    } else if (req.url === '/favicon.ico') {
        res.writeHead(204);
        res.end();
    } else {
        res.writeHead(404);
        res.end('Not Found');
    }
});

// ==================== WebSocket服务器 ====================
const wss = new WebSocket.Server({ server });

// 游戏房间管理
const tables = new Map();
const playerToTable = new Map();
let tableCounter = 0;

// ==================== 牌面常量 ====================
const SUITS = ['筒', '条', '万'];
const RANKS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
const WINDS = ['东', '南', '西', '北'];
const ARROWS = ['中', '发', '白'];

// 创建一副麻将牌
function createDeck() {
    const deck = [];

    // 筒条万 (每种4张)
    for (const suit of SUITS) {
        for (const rank of RANKS) {
            for (let i = 0; i < 4; i++) {
                deck.push({
                    suit,
                    rank,
                    type: 'number',
                    id: `${suit}${rank}_${i}`
                });
            }
        }
    }

    // 风牌 (每种4张)
    for (const wind of WINDS) {
        for (let i = 0; i < 4; i++) {
            deck.push({
                suit: '风',
                rank: wind,
                type: 'wind',
                id: `风${wind}_${i}`
            });
        }
    }

    // 箭牌 (每种4张)
    for (const arrow of ARROWS) {
        for (let i = 0; i < 4; i++) {
            deck.push({
                suit: '箭',
                rank: arrow,
                type: 'arrow',
                id: `箭${arrow}_${i}`
            });
        }
    }

    return deck; // 136张
}

// 洗牌
function shuffle(deck) {
    const shuffled = [...deck];
    for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
}

// 牌的显示名称
function cardName(card) {
    if (card.type === 'number') {
        return `${card.rank}${card.suit}`;
    } else {
        return card.rank;
    }
}

// ==================== 牌桌类 ====================
class GameTable {
    constructor(id, tableNumber) {
        this.id = id;
        this.tableNumber = tableNumber;
        this.players = new Map(); // playerId -> player info
        this.spectators = new Map();
        this.maxPlayers = 4;
        this.gameTimer = null; // 游戏计时器

        this.gameState = {
            started: false,
            currentPlayer: 0, // 0-3, 当前出牌玩家索引
            dealer: 0, // 庄家索引
            deck: [], // 牌堆
            hands: {}, // playerId -> cards[]
            wildCard: null, // 万能牌
            discardedPile: [], // 打出的牌
            showedCards: {}, // playerId -> { fa: [], gang: [] }
            faUsed: {}, // playerId -> 玩家是否已换过发
            lastDrawn: null, // 最后摸的牌
            gameStartTime: null, // 游戏开始时间
            totalGameTime: 0 // 游戏总时长（秒）
        };
    }

    // 获取按座位排序的玩家ID数组
    getSortedPlayerIds() {
        return Array.from(this.players.entries())
            .sort((a, b) => a[1].seatNum - b[1].seatNum)
            .map(([id]) => id);
    }

    // 添加玩家
    addPlayer(ws, playerId, playerName, seatNum = null) {
        if (this.players.size >= this.maxPlayers) return false;
        if (this.gameState.started) return false;

        let actualSeat;
        if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
            const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
            if (occupied) return false;
            actualSeat = seatNum;
        } else {
            const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
            for (let i = 1; i <= 4; i++) {
                if (!occupiedSeats.has(i)) {
                    actualSeat = i;
                    break;
                }
            }
        }

        this.players.set(playerId, {
            ws,
            id: playerId,
            name: playerName,
            seatNum: actualSeat,
            ready: false,
            isAI: false
        });

        return true;
    }

    // 移除玩家
    removePlayer(playerId) {
        this.players.delete(playerId);
        return this.players.size === 0;
    }

    // 设置准备状态
    setPlayerReady(playerId, ready) {
        const player = this.players.get(playerId);
        if (player) {
            player.ready = ready;
            this.broadcastPlayerList();
            this.checkStartGame();
        }
    }

    // 检查是否可以开始游戏
    checkStartGame() {
        const allReady = Array.from(this.players.values()).every(p => p.ready);
        if (allReady && this.players.size === 4 && !this.gameState.started) {
            this.startGame();
        }
    }

    // 开始游戏
    startGame() {
        this.gameState.started = true;
        this.gameState.gameStartTime = Date.now();
        this.gameState.totalGameTime = 0;

        // 启动游戏计时器（每秒更新）
        this.gameTimer = setInterval(() => {
            if (this.gameState.started) {
                this.gameState.totalGameTime = Math.floor((Date.now() - this.gameState.gameStartTime) / 1000);
            }
        }, 1000);

        // 洗牌
        this.gameState.deck = shuffle(createDeck());

        // 确定万能牌（随机翻一张）
        const wildIndex = Math.floor(Math.random() * this.gameState.deck.length);
        this.gameState.wildCard = this.gameState.deck[wildIndex];

        // 初始化手牌和展示区
        const playerIds = this.getSortedPlayerIds();
        for (const pid of playerIds) {
            this.gameState.hands[pid] = [];
            this.gameState.showedCards[pid] = { fa: [], gang: [] };
            this.gameState.faUsed[pid] = false;
        }

        // 发牌：每人4张×3轮，然后每人1张，庄家多1张
        // 庄家是1号位(seatNum=1)，对应索引0
        const dealerIndex = playerIds.findIndex(pid => this.players.get(pid).seatNum === 1);
        this.gameState.dealer = dealerIndex >= 0 ? dealerIndex : 0;

        // 每人4张×3轮
        for (let round = 0; round < 3; round++) {
            for (const pid of playerIds) {
                for (let i = 0; i < 4; i++) {
                    const card = this.gameState.deck.pop();
                    if (card) this.gameState.hands[pid].push(card);
                }
            }
        }

        // 每人1张
        for (const pid of playerIds) {
            const card = this.gameState.deck.pop();
            if (card) this.gameState.hands[pid].push(card);

