    36→
    37→// ==================== WebSocket服务器 ====================
    38→const wss = new WebSocket.Server({ server });
    39→
    40→// 游戏房间管理
    41→const tables = new Map();
    42→const playerToTable = new Map();
    43→let tableCounter = 0;
    44→
    45→// ==================== 牌面常量 ====================
    46→const SUITS = ['筒', '条', '万'];
    47→const RANKS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
    48→const WINDS = ['东', '南', '西', '北'];
    49→const ARROWS = ['中', '发', '白'];
    50→
    51→// 创建一副麻将牌
    52→function createDeck() {
    53→    const deck = [];
    54→
    55→    // 筒条万 (每种4张)
    56→    for (const suit of SUITS) {
    57→        for (const rank of RANKS) {
    58→            for (let i = 0; i < 4; i++) {
    59→                deck.push({
    60→                    suit,
    61→                    rank,
    62→                    type: 'number',
    63→                    id: `${suit}${rank}_${i}`
    64→                });
    65→            }
    66→        }
    67→    }
    68→
    69→    // 风牌 (每种4张)
    70→    for (const wind of WINDS) {
    71→        for (let i = 0; i < 4; i++) {
    72→            deck.push({
    73→                suit: '风',
    74→                rank: wind,
    75→                type: 'wind',
    76→                id: `风${wind}_${i}`
    77→            });
    78→        }
    79→    }
    80→
    81→    // 箭牌 (每种4张)
    82→    for (const arrow of ARROWS) {
    83→        for (let i = 0; i < 4; i++) {
    84→            deck.push({
    85→                suit: '箭',
    86→                rank: arrow,
    87→                type: 'arrow',
    88→                id: `箭${arrow}_${i}`
    89→            });
    90→        }
    91→    }
    92→
    93→    return deck; // 136张
    94→}
    95→
    96→// 洗牌
    97→function shuffle(deck) {
    98→    const shuffled = [...deck];
    99→    for (let i = shuffled.length - 1; i > 0; i--) {
   100→        const j = Math.floor(Math.random() * (i + 1));
   101→        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
   102→    }
   103→    return shuffled;
   104→}
   105→
   106→// 牌的显示名称
   107→function cardName(card) {
   108→    if (card.type === 'number') {
   109→        return `${card.rank}${card.suit}`;
   110→    } else {
   111→        return card.rank;
   112→    }
   113→}
   114→
   115→// ==================== 牌桌类 ====================
   116→class GameTable {
   117→    constructor(id, tableNumber) {
   118→        this.id = id;
   119→        this.tableNumber = tableNumber;
   120→        this.players = new Map(); // playerId -> player info
   121→        this.spectators = new Map();
   122→        this.maxPlayers = 4;
   123→        this.gameTimer = null; // 游戏计时器
   124→        this.lastSeatShuffleTime = Date.now(); // 上次换座位时间
   125→        this.sessionStartTime = Date.now(); // 会话开始时间
   126→
   127→        this.gameState = {
   128→            started: false,
   129→            currentPlayer: 0, // 0-3, 当前出牌玩家索引
   130→            dealer: 0, // 庄家索引
   131→            deck: [], // 牌堆
   132→            hands: {}, // playerId -> cards[]
   133→            wildCard: null, // 万能牌
   134→            discardedPile: [], // 打出的牌
   135→            showedCards: {}, // playerId -> { fa: [], gang: [] }
   136→            faUsed: {}, // playerId -> 玩家是否已换过发
   137→            lastDrawn: null, // 最后摸的牌
   138→            gameStartTime: null, // 游戏开始时间
   139→            totalGameTime: 0 // 游戏总时长（秒）
   140→        };
   141→    }
   142→
   143→    // 获取按座位排序的玩家ID数组
   144→    getSortedPlayerIds() {
   145→        return Array.from(this.players.entries())
   146→            .sort((a, b) => a[1].seatNum - b[1].seatNum)
   147→            .map(([id]) => id);
   148→    }
   149→
   150→    // 添加玩家
   151→    addPlayer(ws, playerId, playerName, seatNum = null) {
   152→        if (this.players.size >= this.maxPlayers) return false;
   153→        if (this.gameState.started) return false;
   154→
   155→        let actualSeat;
   156→        if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
   157→            const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
   158→            if (occupied) return false;
   159→            actualSeat = seatNum;
   160→        } else {
   161→            const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
   162→            for (let i = 1; i <= 4; i++) {
   163→                if (!occupiedSeats.has(i)) {
   164→                    actualSeat = i;
   165→                    break;
   166→                }
   167→            }
   168→        }
   169→
   170→        this.players.set(playerId, {
   171→            ws,
   172→            id: playerId,
   173→            name: playerName,
   174→            seatNum: actualSeat,
   175→            ready: false,
   176→            isAI: false
   177→        });
   178→
   179→        return true;
   180→    }
   181→
   182→    // 移除玩家
   183→    removePlayer(playerId) {
   184→        this.players.delete(playerId);
   185→        return this.players.size === 0;
   186→    }
   187→
   188→    // 设置准备状态
   189→    setPlayerReady(playerId, ready) {
   190→        const player = this.players.get(playerId);
   191→        if (player) {
   192→            player.ready = ready;
   193→            this.broadcastPlayerList();
   194→            this.checkStartGame();
   195→        }
   196→    }
   197→
   198→    // 检查是否可以开始游戏
   199→    checkStartGame() {
   200→        const allReady = Array.from(this.players.values()).every(p => p.ready);
   201→        if (allReady && this.players.size === 4 && !this.gameState.started) {
   202→            // 检查是否需要随机换座位（每隔1小时）
   203→            const timeSinceLastShuffle = Date.now() - this.lastSeatShuffleTime;
   204→            if (timeSinceLastShuffle >= 3600000) { // 1小时 = 3600000毫秒
   205→                this.randomizeSeats();
   206→                this.lastSeatShuffleTime = Date.now();
   207→                this.broadcastMessage('⏰ 游戏已进行1小时，座位已随机更换！');
   208→            }
   209→            this.startGame();
   210→        }
   211→    }
   212→
   213→    // 随机换座位
   214→    randomizeSeats() {
   215→        const playerList = Array.from(this.players.values());
   216→        const seats = [1, 2, 3, 4];
   217→
   218→        // 洗牌座位
   219→        for (let i = seats.length - 1; i > 0; i--) {
   220→            const j = Math.floor(Math.random() * (i + 1));
   221→            [seats[i], seats[j]] = [seats[j], seats[i]];
   222→        }
   223→
   224→        // 分配新座位
   225→        playerList.forEach((player, index) => {
   226→            player.seatNum = seats[index];
   227→        });
   228→
   229→        console.log(`牌桌${this.tableNumber} 座位已随机更换`);
   230→        this.broadcastPlayerList();
   231→    }
   232→
   233→    // 开始游戏
   234→    startGame() {
   235→        this.gameState.started = true;
   236→        this.gameState.gameStartTime = Date.now();
   237→        this.gameState.totalGameTime = 0;
   238→
   239→        // 启动游戏计时器（每秒更新）
   240→        this.gameTimer = setInterval(() => {
   241→            if (this.gameState.started) {
   242→                this.gameState.totalGameTime = Math.floor((Date.now() - this.gameState.gameStartTime) / 1000);
   243→            }
   244→        }, 1000);
   245→
   246→        // 洗牌
   247→        this.gameState.deck = shuffle(createDeck());
   248→
   249→        // 确定万能牌（随机翻一张）
   250→        const wildIndex = Math.floor(Math.random() * this.gameState.deck.length);
   251→        this.gameState.wildCard = this.gameState.deck[wildIndex];
   252→
   253→        // 初始化手牌和展示区
   254→        const playerIds = this.getSortedPlayerIds();
   255→        for (const pid of playerIds) {
   256→            this.gameState.hands[pid] = [];
   257→            this.gameState.showedCards[pid] = { fa: [], gang: [] };
   258→            this.gameState.faUsed[pid] = false;
   259→        }
   260→
   261→        // 发牌：每人4张×3轮，然后每人1张，庄家多1张
   262→        // 庄家是1号位(seatNum=1)，对应索引0
   263→        const dealerIndex = playerIds.findIndex(pid => this.players.get(pid).seatNum === 1);
   264→        this.gameState.dealer = dealerIndex >= 0 ? dealerIndex : 0;
   265→
   266→        // 每人4张×3轮
   267→        for (let round = 0; round < 3; round++) {
   268→            for (const pid of playerIds) {
   269→                for (let i = 0; i < 4; i++) {
   270→                    const card = this.gameState.deck.pop();
   271→                    if (card) this.gameState.hands[pid].push(card);
   272→                }
   273→            }
   274→        }
   275→
   276→        // 每人1张
   277→        for (const pid of playerIds) {
   278→            const card = this.gameState.deck.pop();
   279→            if (card) this.gameState.hands[pid].push(card);
   280→        }
   281→
   282→        // 庄家多拿1张
   283→        const dealerPid = playerIds[this.gameState.dealer];
   284→        const extraCard = this.gameState.deck.pop();
   285→        if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
   286→
   287→        // 庄家先出牌
   288→        this.gameState.currentPlayer = this.gameState.dealer;
   289→
   290→        // 排序手牌
   291→        for (const pid of playerIds) {
   292→            this.sortHand(pid);
   293→        }
   294→
   295→        console.log(`牌桌${this.tableNumber} 游戏开始，万能牌: ${cardName(this.gameState.wildCard)}`);
   296→
   297→        this.broadcastGameState();
   298→    }
   299→
   300→    // 排序手牌
   301→    sortHand(playerId) {
   302→        const hand = this.gameState.hands[playerId];
   303→        if (!hand) return;
   304→
   305→        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
   306→        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
   307→        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
   308→
   309→        hand.sort((a, b) => {
   310→            // 万能牌放最后
   311→            if (this.isWildCard(a) && !this.isWildCard(b)) return 1;
   312→            if (!this.isWildCard(a) && this.isWildCard(b)) return -1;
   313→
   314→            const suitA = suitOrder[a.suit] ?? 5;
   315→            const suitB = suitOrder[b.suit] ?? 5;
   316→            if (suitA !== suitB) return suitA - suitB;
   317→
   318→            if (a.type === 'number' && b.type === 'number') {
   319→                return a.rank - b.rank;
   320→            } else if (a.type === 'wind' && b.type === 'wind') {
   321→                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
   322→            } else if (a.type === 'arrow' && b.type === 'arrow') {
   323→                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
   324→            }
   325→            return 0;
   326→        });
   327→    }
   328→
   329→    // 判断是否是万能牌（相同牌或红中）
   330→    isWildCard(card) {
   331→        const wild = this.gameState.wildCard;
   332→        if (!wild) return false;
   333→
   334→        // 相同牌是万能牌
   335→        if (card.suit === wild.suit && card.rank === wild.rank) return true;
   336→        // 红中也是万能牌
   337→        if (card.type === 'arrow' && card.rank === '中') return true;
   338→
   339→        return false;
   340→    }
   341→
   342→    // 摸牌
   343→    drawCard(playerId) {
   344→        if (this.gameState.deck.length === 0) {
   345→            return null; // 流局
   346→        }
   347→
   348→        const card = this.gameState.deck.pop();
   349→        if (card) {
   350→            this.gameState.hands[playerId].push(card);
   351→            this.gameState.lastDrawn = card;
   352→            this.sortHand(playerId);
   353→        }
   354→        return card;
   355→    }
   356→
   357→    // 出牌
   358→    playCard(playerId, cardId) {
   359→        const hand = this.gameState.hands[playerId];
   360→        if (!hand) return false;
   361→
   362→        const cardIndex = hand.findIndex(c => c.id === cardId);
   363→        if (cardIndex === -1) return false;
   364→
   365→        const card = hand.splice(cardIndex, 1)[0];
   366→
   367→        // 打出的牌背面朝上，加入弃牌堆
   368→        this.gameState.discardedPile.push({
   369→            playerId,
   370→            card,
   371→            hidden: true // 背面朝上
   372→        });
   373→
   374→        // 下一位玩家
   375→        this.nextPlayer();
   376→
   377→        return true;
   378→    }
   379→
   380→    // 换"发"
   381→    changeFa(playerId) {
   382→        // 检查是否已换过
   383→        if (this.gameState.faUsed[playerId]) return false;
   384→
   385→        const hand = this.gameState.hands[playerId];
   386→        if (!hand) return false;
   387→
   388→        // 找"发"牌
   389→        const faIndex = hand.findIndex(c => c.type === 'arrow' && c.rank === '发');
   390→        if (faIndex === -1) return false;
   391→
   392→        // 移出"发"到展示区
   393→        const faCard = hand.splice(faIndex, 1)[0];
   394→        this.gameState.showedCards[playerId].fa.push(faCard);
   395→        this.gameState.faUsed[playerId] = true;
   396→
   397→        // 摸一张新牌
   398→        const newCard = this.drawCard(playerId);
   399→
   400→        return { faCard, newCard };
   401→    }
   402→
   403→    // 暗杠
   404→    doGang(playerId, cardId) {
   405→        const hand = this.gameState.hands[playerId];
   406→        if (!hand) return false;
   407→
   408→        // 找到这张牌
   409→        const targetCard = hand.find(c => c.id === cardId);
   410→        if (!targetCard) return false;
   411→
   412→        // 找所有相同的牌（不包括万能牌替代）
   413→        const sameCards = hand.filter(c =>
   414→            c.suit === targetCard.suit && c.rank === targetCard.rank
   415→        );
   416→
   417→        if (sameCards.length !== 4) return false;
   418→
   419→        // 移除这4张牌
   420→        this.gameState.hands[playerId] = hand.filter(c =>
   421→            !(c.suit === targetCard.suit && c.rank === targetCard.rank)
   422→        );
   423→
   424→        // 加入展示区
   425→        this.gameState.showedCards[playerId].gang.push(sameCards);
   426→
   427→        return sameCards;
   428→    }
   429→
   430→    // 检查是否可以暗杠
   431→    canGang(playerId) {
   432→        const hand = this.gameState.hands[playerId];
   433→        if (!hand) return [];
   434→
   435→        const counts = {};
   436→        for (const card of hand) {
   437→            const key = `${card.suit}_${card.rank}`;
   438→            counts[key] = (counts[key] || 0) + 1;
   439→        }
   440→
   441→        const gangable = [];
   442→        for (const [key, count] of Object.entries(counts)) {
   443→            if (count === 4) {
   444→                const [suit, rank] = key.split('_');
   445→                gangable.push({ suit, rank });
   446→            }
   447→        }
   448→
   449→        return gangable;
   450→    }
   451→
   452→    // 检查是否有"发"可以换
   453→    hasFa(playerId) {
   454→        const hand = this.gameState.hands[playerId];
   455→        if (!hand) return false;
   456→
   457→        return hand.some(c => c.type === 'arrow' && c.rank === '发') &&
   458→               !this.gameState.faUsed[playerId];
   459→    }
   460→
   461→    // 下一位玩家
   462→    nextPlayer() {
   463→        this.gameState.currentPlayer = (this.gameState.currentPlayer + 1) % 4;
   464→    }
   465→
   466→    // 获取当前玩家ID
   467→    getCurrentPlayerId() {
   468→        const playerIds = this.getSortedPlayerIds();
   469→        return playerIds[this.gameState.currentPlayer];
   470→    }
   471→
   472→    // 广播玩家列表
   473→    broadcastPlayerList() {
   474→        const players = Array.from(this.players.values()).map(p => ({
   475→            id: p.id,
   476→            name: p.name,
   477→            seatNum: p.seatNum,
   478→            ready: p.ready,
   479→            isAI: p.isAI
   480→        }));
   481→
   482→        const message = JSON.stringify({
   483→            type: 'playerList',
   484→            players,
   485→            tableNumber: this.tableNumber,
   486→            started: this.gameState.started
   487→        });
   488→
   489→        for (const player of this.players.values()) {
   490→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   491→                player.ws.send(message);
   492→            }
   493→        }
   494→
   495→        for (const spectator of this.spectators.values()) {
   496→            if (spectator.ws && spectator.ws.readyState === WebSocket.OPEN) {
   497→                spectator.ws.send(message);
   498→            }
   499→        }
   500→    }
   501→
   502→    // 广播游戏状态
   503→    broadcastGameState() {
   504→        const playerIds = this.getSortedPlayerIds();
   505→
   506→        for (const [playerId, player] of this.players) {
   507→            if (!player.ws || player.ws.readyState !== WebSocket.OPEN) continue;
   508→
   509→            const state = this.getPlayerGameState(playerId);
   510→            player.ws.send(JSON.stringify({
   511→                type: 'gameState',
   512→                data: state
   513→            }));
   514→        }
   515→    }
   516→
   517→    // 获取单个玩家视角的游戏状态
   518→    getPlayerGameState(playerId) {
   519→        const playerIds = this.getSortedPlayerIds();
   520→        const myIndex = playerIds.indexOf(playerId);
   521→
   522→        // 构建各玩家信息
   523→        const playerInfo = {};
   524→        for (let i = 0; i < playerIds.length; i++) {
   525→            const pid = playerIds[i];
   526→            const p = this.players.get(pid);
   527→            playerInfo[pid] = {
   528→                name: p?.name || '',
   529→                seatNum: p?.seatNum || (i + 1),
   530→                handCount: this.gameState.hands[pid]?.length || 0,
   531→                showedCards: this.gameState.showedCards[pid] || { fa: [], gang: [] }
   532→            };
   533→        }
   534→
   535→        // 只返回自己的手牌
   536→        const myHand = this.gameState.hands[playerId] || [];
   537→
   538→        return {
   539→            started: this.gameState.started,
   540→            currentPlayer: this.gameState.currentPlayer,
   541→            dealer: this.gameState.dealer,
   542→            myIndex,
   543→            myHand,
   544→            wildCard: this.gameState.wildCard,
   545→            deckCount: this.gameState.deck.length,
   546→            totalGameTime: this.gameState.totalGameTime,
   547→            playerInfo,
   548→            discardedCount: this.gameState.discardedPile.length,
   549→            canChangeFa: this.hasFa(playerId) && this.getCurrentPlayerId() === playerId,
   550→            canGang: this.canGang(playerId).length > 0 && this.getCurrentPlayerId() === playerId
   551→        };
   552→    }
   553→
   554→    // 广播消息
   555→    broadcastMessage(text) {
   556→        const message = JSON.stringify({ type: 'message', text });
   557→        for (const player of this.players.values()) {
   558→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   559→                player.ws.send(message);
   560→            }
   561→        }
   562→    }
   563→
   564→    // 获取牌桌信息（用于大厅显示）
   565→    getTableInfo() {
   566→        return {
   567→            id: this.id,
   568→            tableNumber: this.tableNumber,
   569→            playerCount: this.players.size,
   570→            maxPlayers: this.maxPlayers,
   571→            started: this.gameState.started,
   572→            players: Array.from(this.players.values()).map(p => ({
   573→                name: p.name,
   574→                seatNum: p.seatNum,
   575→                ready: p.ready
   576→            }))
   577→        };
   578→    }
   579→}
