   581→// ==================== WebSocket连接处理 ====================
   582→wss.on('connection', (ws) => {
   583→    let playerId = null;
   584→    let playerName = null;
   585→    let currentTableId = null;
   586→
   587→    console.log('新客户端连接');
   588→
   589→    ws.on('message', (data) => {
   590→        try {
   591→            const msg = JSON.parse(data);
   592→
   593→            switch (msg.type) {
   594→                case 'login':
   595→                    playerId = `player_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
   596→                    playerName = msg.name || '玩家';
   597→                    ws.send(JSON.stringify({
   598→                        type: 'loginSuccess',
   599→                        playerId,
   600→                        playerName
   601→                    }));
   602→
   603→                    // 发送牌桌列表
   604→                    sendTableList(ws);
   605→                    break;
   606→
   607→                case 'getTableList':
   608→                    sendTableList(ws);
   609→                    break;
   610→
   611→                case 'createTable':
   612→                    const newTable = createTable();
   613→                    // 加入牌桌
   614→                    if (joinTable(ws, playerId, playerName, newTable.id, msg.seatNum)) {
   615→                        currentTableId = newTable.id;
   616→                    }
   617→                    break;
   618→
   619→                case 'joinTable':
   620→                    if (joinTable(ws, playerId, playerName, msg.tableId, msg.seatNum)) {
   621→                        currentTableId = msg.tableId;
   622→                    }
   623→                    break;
   624→
   625→                case 'ready':
   626→                    if (currentTableId) {
   627→                        const table = tables.get(currentTableId);
   628→                        if (table) {
   629→                            table.setPlayerReady(playerId, msg.ready);
   630→                        }
   631→                    }
   632→                    break;
   633→
   634→                case 'play':
   635→                    if (currentTableId) {
   636→                        const table = tables.get(currentTableId);
   637→                        if (table && table.getCurrentPlayerId() === playerId) {
   638→                            if (table.playCard(playerId, msg.cardId)) {
   639→                                table.broadcastGameState();
   640→                            }
   641→                        }
   642→                    }
   643→                    break;
   644→
   645→                case 'changeFa':
   646→                    if (currentTableId) {
   647→                        const table = tables.get(currentTableId);
   648→                        if (table && table.getCurrentPlayerId() === playerId) {
   649→                            const result = table.changeFa(playerId);
   650→                            if (result) {
   651→                                table.broadcastMessage(`${playerName} 换了一张"發"`);
   652→                                table.broadcastGameState();
   653→                            }
   654→                        }
   655→                    }
   656→                    break;
   657→
   658→                case 'gang':
   659→                    if (currentTableId) {
   660→                        const table = tables.get(currentTableId);
   661→                        if (table && table.getCurrentPlayerId() === playerId) {
   662→                            const result = table.doGang(playerId, msg.cardId);
   663→                            if (result) {
   664→                                table.broadcastMessage(`${playerName} 暗杠！`);
   665→                                table.broadcastGameState();
   666→                            }
   667→                        }
   668→                    }
   669→                    break;
   670→
   671→                case 'draw':
   672→                    if (currentTableId) {
   673→                        const table = tables.get(currentTableId);
   674→                        if (table && table.getCurrentPlayerId() === playerId) {
   675→                            const card = table.drawCard(playerId);
   676→                            if (card) {
   677→                                table.broadcastGameState();
   678→                            } else {
   679→                                table.broadcastMessage('牌堆已空，流局！');
   680→                            }
   681→                        }
   682→                    }
   683→                    break;
   684→
   685→                case 'chat':
   686→                    if (currentTableId) {
   687→                        const table = tables.get(currentTableId);
   688→                        if (table) {
   689→                            table.broadcastMessage(`${playerName}: ${msg.text}`);
   690→                        }
   691→                    }
   692→                    break;
   693→            }
   694→        } catch (e) {
   695→            console.error('消息处理错误:', e);
   696→        }
   697→    });
   698→
   699→    ws.on('close', () => {
   700→        console.log('客户端断开:', playerName);
   701→
   702→        if (currentTableId && playerId) {
   703→            const table = tables.get(currentTableId);
   704→            if (table) {
   705→                // 游戏进行中不删除玩家，只标记断开
   706→                const player = table.players.get(playerId);
   707→                if (player) {
   708→                    player.ws = null;
   709→                    player.ready = false;
   710→                }
   711→
   712→                // 如果游戏未开始且房间为空，删除房间
   713→                if (!table.gameState.started && table.removePlayer(playerId)) {
   714→                    tables.delete(currentTableId);
   715→                    console.log(`牌桌 ${currentTableId} 已删除`);
   716→                }
   717→
   718→                table.broadcastPlayerList();
   719→            }
   720→            playerToTable.delete(playerId);
   721→        }
   722→    });
   723→});
