   725→// 发送牌桌列表
   726→function sendTableList(ws) {
   727→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
   728→    ws.send(JSON.stringify({
   729→        type: 'tableList',
   730→        tables: tableList
   731→    }));
