   734→// 创建牌桌
   735→function createTable() {
   736→    tableCounter++;
   737→    const tableId = `table_${tableCounter}`;
   738→    const table = new GameTable(tableId, tableCounter);
   739→    tables.set(tableId, table);
   740→    console.log(`创建新牌桌: ${tableId}`);
