    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 15px;
    padding: 20px;
}

.table-card {
    background: rgba(255,255,255,0.1);
    border-radius: 10px;
    padding: 15px;
    text-align: center;
    cursor: pointer;
    transition: all 0.3s;
    border: 2px solid transparent;
}

.table-card:hover {
    background: rgba(255,255,255,0.2);
    transform: translateY(-2px);
}

.table-card.empty {
    border-color: #4CAF50;
}

.table-card.waiting {
    border-color: #FFC107;
}

.table-card.playing {
    border-color: #2196F3;
}

.table-card.full {
    border-color: #f44336;
    opacity: 0.7;
}

.table-card.new-table {
    background: rgba(76, 175, 80, 0.3);
    border: 2px dashed #4CAF50;
}

.table-number {
    font-size: 1.5em;
    font-weight: bold;
    margin-bottom: 10px;
}

.table-status {
    font-size: 0.9em;
    color: #ccc;
}

.table-players {
    margin-top: 10px;
