}

/* 游戏界面样式 */
.game-container {
    display: none;
    width: 100vw;
    height: 100vh;
    position: relative;
}

.game-table {
    width: 100%;
    height: 100%;
    position: relative;
    background: radial-gradient(ellipse at center, #2d5a3d 0%, #1a472a 100%);
}

/* 玩家区域 */
.player-area {
    position: absolute;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.player-area.bottom {
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%);
    width: 80%;
}

.player-area.top {
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
}

.player-area.left {
    left: 10px;
    top: 50%;
    transform: translateY(-50%);
}

