function renderTableList(tables) {
    const container = document.getElementById('tableList');
    container.innerHTML = '';

    // 现有牌桌
    tables.forEach(table => {
        const card = document.createElement('div');
        card.className = 'table-card';

        let statusClass = 'empty';
        let statusText = '空桌';

        if (table.started) {
            statusClass = 'playing';
            statusText = '游戏中';
        } else if (table.playerCount === 4) {
            statusClass = 'full';
            statusText = '已满';
        } else if (table.playerCount > 0) {
            statusClass = 'waiting';
            statusText = `等待中 ${table.playerCount}/4`;
        }

        card.classList.add(statusClass);

        let playersHtml = '';
        if (table.players.length > 0) {
            playersHtml = '<div class="table-players">' +
                table.players.map(p => `<div>${p.seatNum}号: ${p.name}${p.ready ? ' ✓' : ''}</div>`).join('') +
                '</div>';
        }

        card.innerHTML = `
            <div class="table-number">${table.tableNumber}号桌</div>
            <div class="table-status">${statusText}</div>
            ${playersHtml}
        `;

        if (!table.started && table.playerCount < 4) {
            card.onclick = () => joinTable(table.id);
        }

