     1→// 桐城自摸麻将 - 局域网服务器
     2→// 运行方式: node majiang-server.js
     3→
     4→const http = require('http');
     5→const fs = require('fs');
     6→const path = require('path');
     7→const WebSocket = require('ws');
     8→
     9→const PORT = 8082;
    10→
    11→// ==================== HTTP服务器 ====================
    12→const server = http.createServer((req, res) => {
    13→    console.log(`HTTP请求: ${req.url}`);
    14→
    15→    if (req.url === '/' || req.url === '/index.html') {
    16→        const htmlPath = path.join(__dirname, 'majiang-lan.html');
    17→        fs.readFile(htmlPath, (err, data) => {
    18→            if (err) {
    19→                res.writeHead(404);
    20→                res.end('游戏文件未找到');
    21→                return;
    22→            }
    23→            res.writeHead(200, {
    24→                'Content-Type': 'text/html; charset=utf-8'
    25→            });
    26→            res.end(data);
    27→        });
    28→    } else if (req.url === '/favicon.ico') {
    29→        res.writeHead(204);
    30→        res.end();
    31→    } else {
    32→        res.writeHead(404);
    33→        res.end('Not Found');
    34→    }
    35→});
    36→
    37→// ==================== WebSocket服务器 ====================
    38→const wss = new WebSocket.Server({ server });
    39→
    40→// 游戏房间管理
    41→const tables = new Map();
    42→const playerToTable = new Map();
    43→let tableCounter = 0;
    44→
    45→// ==================== 牌面常量 ====================
    46→const SUITS = ['筒', '条', '万'];
    47→const RANKS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
    48→const WINDS = ['东', '南', '西', '北'];
    49→const ARROWS = ['中', '发', '白'];
    50→
    51→// 创建一副麻将牌
    52→function createDeck() {
    53→    const deck = [];
    54→
    55→    // 筒条万 (每种4张)
    56→    for (const suit of SUITS) {
    57→        for (const rank of RANKS) {
    58→            for (let i = 0; i < 4; i++) {
    59→                deck.push({
    60→                    suit,
    61→                    rank,
    62→                    type: 'number',
    63→                    id: `${suit}${rank}_${i}`
    64→                });
    65→            }
    66→        }
    67→    }
    68→
    69→    // 风牌 (每种4张)
    70→    for (const wind of WINDS) {
    71→        for (let i = 0; i < 4; i++) {
    72→            deck.push({
    73→                suit: '风',
    74→                rank: wind,
    75→                type: 'wind',
    76→                id: `风${wind}_${i}`
    77→            });
    78→        }
    79→    }
    80→
    81→    // 箭牌 (每种4张)
    82→    for (const arrow of ARROWS) {
    83→        for (let i = 0; i < 4; i++) {
    84→            deck.push({
    85→                suit: '箭',
    86→                rank: arrow,
    87→                type: 'arrow',
    88→                id: `箭${arrow}_${i}`
    89→            });
    90→        }
    91→    }
    92→
    93→    return deck; // 136张
    94→}
    95→
    96→// 洗牌
    97→function shuffle(deck) {
    98→    const shuffled = [...deck];
    99→    for (let i = shuffled.length - 1; i > 0; i--) {
   100→        const j = Math.floor(Math.random() * (i + 1));
   101→        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
   102→    }
   103→    return shuffled;
   104→}
   105→
   106→// 牌的显示名称
   107→function cardName(card) {
   108→    if (card.type === 'number') {
   109→        return `${card.rank}${card.suit}`;
   110→    } else {
   111→        return card.rank;
   112→    }
   113→}
   114→
   115→// ==================== 牌桌类 ====================
   116→class GameTable {
   117→    constructor(id, tableNumber) {
   118→        this.id = id;
   119→        this.tableNumber = tableNumber;
   120→        this.players = new Map(); // playerId -> player info
   121→        this.spectators = new Map();
   122→        this.maxPlayers = 4;
   123→        this.gameTimer = null; // 游戏计时器
   124→        this.lastSeatShuffleTime = Date.now(); // 上次换座位时间
   125→        this.sessionStartTime = Date.now(); // 会话开始时间
   126→
   127→        this.gameState = {
   128→            started: false,
   129→            currentPlayer: 0, // 0-3, 当前出牌玩家索引
   130→            dealer: 0, // 庄家索引
   131→            deck: [], // 牌堆
   132→            hands: {}, // playerId -> cards[]
   133→            wildCard: null, // 万能牌
   134→            discardedPile: [], // 打出的牌
   135→            showedCards: {}, // playerId -> { fa: [], gang: [] }
   136→            faUsed: {}, // playerId -> 玩家是否已换过发
   137→            lastDrawn: null, // 最后摸的牌
   138→            gameStartTime: null, // 游戏开始时间
   139→            totalGameTime: 0 // 游戏总时长（秒）
   140→        };
   141→    }
   142→
   143→    // 获取按座位排序的玩家ID数组
   144→    getSortedPlayerIds() {
   145→        return Array.from(this.players.entries())
   146→            .sort((a, b) => a[1].seatNum - b[1].seatNum)
   147→            .map(([id]) => id);
   148→    }
   149→
   150→    // 添加玩家
   151→    addPlayer(ws, playerId, playerName, seatNum = null) {
   152→        if (this.players.size >= this.maxPlayers) return false;
   153→        if (this.gameState.started) return false;
   154→
   155→        let actualSeat;
   156→        if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
   157→            const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
   158→            if (occupied) return false;
   159→            actualSeat = seatNum;
   160→        } else {
   161→            const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
   162→            for (let i = 1; i <= 4; i++) {
   163→                if (!occupiedSeats.has(i)) {
   164→                    actualSeat = i;
   165→                    break;
   166→                }
   167→            }
   168→        }
   169→
   170→        this.players.set(playerId, {
   171→            ws,
   172→            id: playerId,
   173→            name: playerName,
   174→            seatNum: actualSeat,
   175→            ready: false,
   176→            isAI: false
   177→        });
   178→
   179→        return true;
   180→    }
   181→
   182→    // 移除玩家
   183→    removePlayer(playerId) {
   184→        this.players.delete(playerId);
   185→        return this.players.size === 0;
   186→    }
   187→
   188→    // 设置准备状态
   189→    setPlayerReady(playerId, ready) {
   190→        const player = this.players.get(playerId);
   191→        if (player) {
   192→            player.ready = ready;
   193→            this.broadcastPlayerList();
   194→            this.checkStartGame();
   195→        }
   196→    }
   197→
   198→    // 检查是否可以开始游戏
   199→    checkStartGame() {
   200→        const allReady = Array.from(this.players.values()).every(p => p.ready);
   201→        if (allReady && this.players.size === 4 && !this.gameState.started) {
   202→            // 检查是否需要随机换座位（每隔1小时）
   203→            const timeSinceLastShuffle = Date.now() - this.lastSeatShuffleTime;
   204→            if (timeSinceLastShuffle >= 3600000) { // 1小时 = 3600000毫秒
   205→                this.randomizeSeats();
   206→                this.lastSeatShuffleTime = Date.now();
   207→                this.broadcastMessage('⏰ 游戏已进行1小时，座位已随机更换！');
   208→            }
   209→            this.startGame();
   210→        }
   211→    }
   212→
   213→    // 随机换座位
   214→    randomizeSeats() {
   215→        const playerList = Array.from(this.players.values());
   216→        const seats = [1, 2, 3, 4];
   217→
   218→        // 洗牌座位
   219→        for (let i = seats.length - 1; i > 0; i--) {
   220→            const j = Math.floor(Math.random() * (i + 1));
   221→            [seats[i], seats[j]] = [seats[j], seats[i]];
   222→        }
   223→
   224→        // 分配新座位
   225→        playerList.forEach((player, index) => {
   226→            player.seatNum = seats[index];
   227→        });
   228→
   229→        console.log(`牌桌${this.tableNumber} 座位已随机更换`);
   230→        this.broadcastPlayerList();
   231→    }
   232→
   233→    // 开始游戏
   234→    startGame() {
   235→        this.gameState.started = true;
   236→        this.gameState.gameStartTime = Date.now();
   237→        this.gameState.totalGameTime = 0;
   238→
   239→        // 启动游戏计时器（每秒更新）
   240→        this.gameTimer = setInterval(() => {
   241→            if (this.gameState.started) {
   242→                this.gameState.totalGameTime = Math.floor((Date.now() - this.gameState.gameStartTime) / 1000);
   243→            }
   244→        }, 1000);
   245→
   246→        // 洗牌
   247→        this.gameState.deck = shuffle(createDeck());
   248→
   249→        // 确定万能牌（随机翻一张）
   250→        const wildIndex = Math.floor(Math.random() * this.gameState.deck.length);
   251→        this.gameState.wildCard = this.gameState.deck[wildIndex];
   252→
   253→        // 初始化手牌和展示区
   254→        const playerIds = this.getSortedPlayerIds();
   255→        for (const pid of playerIds) {
   256→            this.gameState.hands[pid] = [];
   257→            this.gameState.showedCards[pid] = { fa: [], gang: [] };
   258→            this.gameState.faUsed[pid] = false;
   259→        }
   260→
   261→        // 发牌：每人4张×3轮，然后每人1张，庄家多1张
   262→        // 庄家是1号位(seatNum=1)，对应索引0
   263→        const dealerIndex = playerIds.findIndex(pid => this.players.get(pid).seatNum === 1);
   264→        this.gameState.dealer = dealerIndex >= 0 ? dealerIndex : 0;
   265→
   266→        // 每人4张×3轮
   267→        for (let round = 0; round < 3; round++) {
   268→            for (const pid of playerIds) {
   269→                for (let i = 0; i < 4; i++) {
   270→                    const card = this.gameState.deck.pop();
   271→                    if (card) this.gameState.hands[pid].push(card);
   272→                }
   273→            }
   274→        }
   275→
   276→        // 每人1张
   277→        for (const pid of playerIds) {
   278→            const card = this.gameState.deck.pop();
   279→            if (card) this.gameState.hands[pid].push(card);
   280→        }
   281→
   282→        // 庄家多拿1张
   283→        const dealerPid = playerIds[this.gameState.dealer];
   284→        const extraCard = this.gameState.deck.pop();
   285→        if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
   286→
   287→        // 庄家先出牌
   288→        this.gameState.currentPlayer = this.gameState.dealer;
   289→
   290→        // 排序手牌
   291→        for (const pid of playerIds) {
   292→            this.sortHand(pid);
   293→        }
   294→
   295→        console.log(`牌桌${this.tableNumber} 游戏开始，万能牌: ${cardName(this.gameState.wildCard)}`);
   296→
   297→        // 先发送发牌动画消息
   298→        this.broadcastDealStart();
   299→
   300→        // 等待发牌动画完成（约3秒）后发送游戏状态
   301→        setTimeout(() => {
   302→            this.broadcastGameState();
   303→        }, 3000);
   304→    }
   305→
   306→    // 广播发牌开始消息
   307→    broadcastDealStart() {
   308→        const message = JSON.stringify({ type: 'dealStart' });
   309→        for (const player of this.players.values()) {
   310→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   311→                player.ws.send(message);
   312→            }
   313→        }
   314→    }
   315→
   316→    // 排序手牌
   317→    sortHand(playerId) {
   318→        const hand = this.gameState.hands[playerId];
   319→        if (!hand) return;
   320→
   321→        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
   322→        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
   323→        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
   324→
   325→        hand.sort((a, b) => {
   326→            // 万能牌放最后
   327→            if (this.isWildCard(a) && !this.isWildCard(b)) return 1;
   328→            if (!this.isWildCard(a) && this.isWildCard(b)) return -1;
   329→
   330→            const suitA = suitOrder[a.suit] ?? 5;
   331→            const suitB = suitOrder[b.suit] ?? 5;
   332→            if (suitA !== suitB) return suitA - suitB;
   333→
   334→            if (a.type === 'number' && b.type === 'number') {
   335→                return a.rank - b.rank;
   336→            } else if (a.type === 'wind' && b.type === 'wind') {
   337→                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
   338→            } else if (a.type === 'arrow' && b.type === 'arrow') {
   339→                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
   340→            }
   341→            return 0;
   342→        });
   343→    }
   344→
   345→    // 判断是否是万能牌（相同牌或红中）
   346→    isWildCard(card) {
   347→        const wild = this.gameState.wildCard;
   348→        if (!wild) return false;
   349→
   350→        // 相同牌是万能牌
   351→        if (card.suit === wild.suit && card.rank === wild.rank) return true;
   352→        // 红中也是万能牌
   353→        if (card.type === 'arrow' && card.rank === '中') return true;
   354→
   355→        return false;
   356→    }
   357→
   358→    // 摸牌
   359→    drawCard(playerId) {
   360→        if (this.gameState.deck.length === 0) {
   361→            return null; // 流局
   362→        }
   363→
   364→        const card = this.gameState.deck.pop();
   365→        if (card) {
   366→            this.gameState.hands[playerId].push(card);
   367→            this.gameState.lastDrawn = card;
   368→            this.sortHand(playerId);
   369→        }
   370→        return card;
   371→    }
   372→
   373→    // 出牌
   374→    playCard(playerId, cardId) {
   375→        const hand = this.gameState.hands[playerId];
   376→        if (!hand) return false;
   377→
   378→        const cardIndex = hand.findIndex(c => c.id === cardId);
   379→        if (cardIndex === -1) return false;
   380→
   381→        const card = hand.splice(cardIndex, 1)[0];
   382→
   383→        // 打出的牌背面朝上，加入弃牌堆
   384→        this.gameState.discardedPile.push({
   385→            playerId,
   386→            card,
   387→            hidden: true // 背面朝上
   388→        });
   389→
   390→        // 下一位玩家
   391→        this.nextPlayer();
   392→
   393→        return true;
   394→    }
   395→
   396→    // 换"发"
   397→    changeFa(playerId) {
   398→        // 检查是否已换过
   399→        if (this.gameState.faUsed[playerId]) return false;
   400→
   401→        const hand = this.gameState.hands[playerId];
   402→        if (!hand) return false;
   403→
   404→        // 找"发"牌
   405→        const faIndex = hand.findIndex(c => c.type === 'arrow' && c.rank === '发');
   406→        if (faIndex === -1) return false;
   407→
   408→        // 移出"发"到展示区
   409→        const faCard = hand.splice(faIndex, 1)[0];
   410→        this.gameState.showedCards[playerId].fa.push(faCard);
   411→        this.gameState.faUsed[playerId] = true;
   412→
   413→        // 摸一张新牌
   414→        const newCard = this.drawCard(playerId);
   415→
   416→        return { faCard, newCard };
   417→    }
   418→
   419→    // 暗杠
   420→    doGang(playerId, cardId) {
   421→        const hand = this.gameState.hands[playerId];
   422→        if (!hand) return false;
   423→
   424→        // 找到这张牌
   425→        const targetCard = hand.find(c => c.id === cardId);
   426→        if (!targetCard) return false;
   427→
   428→        // 找所有相同的牌（不包括万能牌替代）
   429→        const sameCards = hand.filter(c =>
   430→            c.suit === targetCard.suit && c.rank === targetCard.rank
   431→        );
   432→
   433→        if (sameCards.length !== 4) return false;
   434→
   435→        // 移除这4张牌
   436→        this.gameState.hands[playerId] = hand.filter(c =>
   437→            !(c.suit === targetCard.suit && c.rank === targetCard.rank)
   438→        );
   439→
   440→        // 加入展示区
   441→        this.gameState.showedCards[playerId].gang.push(sameCards);
   442→
   443→        return sameCards;
   444→    }
   445→
   446→    // 检查是否可以暗杠
   447→    canGang(playerId) {
   448→        const hand = this.gameState.hands[playerId];
   449→        if (!hand) return [];
   450→
   451→        const counts = {};
   452→        for (const card of hand) {
   453→            const key = `${card.suit}_${card.rank}`;
   454→            counts[key] = (counts[key] || 0) + 1;
   455→        }
   456→
   457→        const gangable = [];
   458→        for (const [key, count] of Object.entries(counts)) {
   459→            if (count === 4) {
   460→                const [suit, rank] = key.split('_');
   461→                gangable.push({ suit, rank });
   462→            }
   463→        }
   464→
   465→        return gangable;
   466→    }
   467→
   468→    // 检查是否有"发"可以换
   469→    hasFa(playerId) {
   470→        const hand = this.gameState.hands[playerId];
   471→        if (!hand) return false;
   472→
   473→        return hand.some(c => c.type === 'arrow' && c.rank === '发') &&
   474→               !this.gameState.faUsed[playerId];
   475→    }
   476→
   477→    // 下一位玩家
   478→    nextPlayer() {
   479→        this.gameState.currentPlayer = (this.gameState.currentPlayer + 1) % 4;
   480→    }
   481→
   482→    // 获取当前玩家ID
   483→    getCurrentPlayerId() {
   484→        const playerIds = this.getSortedPlayerIds();
   485→        return playerIds[this.gameState.currentPlayer];
   486→    }
   487→
   488→    // 广播玩家列表
   489→    broadcastPlayerList() {
   490→        const players = Array.from(this.players.values()).map(p => ({
   491→            id: p.id,
   492→            name: p.name,
   493→            seatNum: p.seatNum,
   494→            ready: p.ready,
   495→            isAI: p.isAI
   496→        }));
   497→
   498→        const message = JSON.stringify({
   499→            type: 'playerList',
   500→            players,
   501→            tableNumber: this.tableNumber,
   502→            started: this.gameState.started
   503→        });
   504→
   505→        for (const player of this.players.values()) {
   506→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   507→                player.ws.send(message);
   508→            }
   509→        }
   510→
   511→        for (const spectator of this.spectators.values()) {
   512→            if (spectator.ws && spectator.ws.readyState === WebSocket.OPEN) {
   513→                spectator.ws.send(message);
   514→            }
   515→        }
   516→    }
   517→
   518→    // 广播游戏状态
   519→    broadcastGameState() {
   520→        const playerIds = this.getSortedPlayerIds();
   521→
   522→        for (const [playerId, player] of this.players) {
   523→            if (!player.ws || player.ws.readyState !== WebSocket.OPEN) continue;
   524→
   525→            const state = this.getPlayerGameState(playerId);
   526→            console.log(`发送游戏状态给 ${player.name}: 手牌数量=${state.myHand.length}`);
   527→            player.ws.send(JSON.stringify({
   528→                type: 'gameState',
   529→                data: state
   530→            }));
   531→        }
   532→    }
   533→
   534→    // 获取单个玩家视角的游戏状态
   535→    getPlayerGameState(playerId) {
   536→        const playerIds = this.getSortedPlayerIds();
   537→        const myIndex = playerIds.indexOf(playerId);
   538→
   539→        // 构建各玩家信息
   540→        const playerInfo = {};
   541→        for (let i = 0; i < playerIds.length; i++) {
   542→            const pid = playerIds[i];
   543→            const p = this.players.get(pid);
   544→            playerInfo[pid] = {
   545→                name: p?.name || '',
   546→                seatNum: p?.seatNum || (i + 1),
   547→                handCount: this.gameState.hands[pid]?.length || 0,
   548→                showedCards: this.gameState.showedCards[pid] || { fa: [], gang: [] }
   549→            };
   550→        }
   551→
   552→        // 只返回自己的手牌
   553→        const myHand = this.gameState.hands[playerId] || [];
   554→
   555→        // 获取当前玩家的座位号
   556→        const currentPid = playerIds[this.gameState.currentPlayer];
   557→        const currentPlayerSeat = this.players.get(currentPid)?.seatNum || 1;
   558→
   559→        // 获取庄家的座位号
   560→        const dealerPid = playerIds[this.gameState.dealer];
   561→        const dealerSeat = this.players.get(dealerPid)?.seatNum || 1;
   562→
   563→        return {
   564→            started: this.gameState.started,
   565→            currentPlayer: this.gameState.currentPlayer,
   566→            currentPlayerSeat,
   567→            dealer: this.gameState.dealer,
   568→            dealerSeat,
   569→            myIndex,
   570→            myHand,
   571→            wildCard: this.gameState.wildCard,
   572→            deckCount: this.gameState.deck.length,
   573→            totalGameTime: this.gameState.totalGameTime,
   574→            playerInfo,
   575→            discardedCount: this.gameState.discardedPile.length,
   576→            canChangeFa: this.hasFa(playerId) && this.getCurrentPlayerId() === playerId,
   577→            canGang: this.canGang(playerId).length > 0 && this.getCurrentPlayerId() === playerId
   578→        };
   579→    }
   580→
   581→    // 广播消息
   582→    broadcastMessage(text) {
   583→        const message = JSON.stringify({ type: 'message', text });
   584→        for (const player of this.players.values()) {
   585→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   586→                player.ws.send(message);
   587→            }
   588→        }
   589→    }
   590→
   591→    // 获取牌桌信息（用于大厅显示）
   592→    getTableInfo() {
   593→        return {
   594→            id: this.id,
   595→            tableNumber: this.tableNumber,
   596→            playerCount: this.players.size,
   597→            maxPlayers: this.maxPlayers,
   598→            started: this.gameState.started,
   599→            players: Array.from(this.players.values()).map(p => ({
   600→                name: p.name,
   601→                seatNum: p.seatNum,
   602→                ready: p.ready
   603→            }))
   604→        };
   605→    }
   606→}
   607→
   608→// ==================== WebSocket连接处理 ====================
   609→wss.on('connection', (ws) => {
   610→    let playerId = null;
   611→    let playerName = null;
   612→    let currentTableId = null;
   613→
   614→    console.log('新客户端连接');
   615→
   616→    ws.on('message', (data) => {
   617→        try {
   618→            const msg = JSON.parse(data);
   619→
   620→            switch (msg.type) {
   621→                case 'login':
   622→                    playerId = `player_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
   623→                    playerName = msg.name || '玩家';
   624→                    ws.send(JSON.stringify({
   625→                        type: 'loginSuccess',
   626→                        playerId,
   627→                        playerName
   628→                    }));
   629→
   630→                    // 发送牌桌列表
   631→                    sendTableList(ws);
   632→                    break;
   633→
   634→                case 'getTableList':
   635→                    sendTableList(ws);
   636→                    break;
   637→
   638→                case 'createTable':
   639→                    const newTable = createTable();
   640→                    // 加入牌桌
   641→                    if (joinTable(ws, playerId, playerName, newTable.id, msg.seatNum)) {
   642→                        currentTableId = newTable.id;
   643→                    }
   644→                    break;
   645→
   646→                case 'joinTable':
   647→                    if (joinTable(ws, playerId, playerName, msg.tableId, msg.seatNum)) {
   648→                        currentTableId = msg.tableId;
   649→                    }
   650→                    break;
   651→
   652→                case 'ready':
   653→                    if (currentTableId) {
   654→                        const table = tables.get(currentTableId);
   655→                        if (table) {
   656→                            table.setPlayerReady(playerId, msg.ready);
   657→                        }
   658→                    }
   659→                    break;
   660→
   661→                case 'play':
   662→                    if (currentTableId) {
   663→                        const table = tables.get(currentTableId);
   664→                        if (table && table.getCurrentPlayerId() === playerId) {
   665→                            if (table.playCard(playerId, msg.cardId)) {
   666→                                table.broadcastGameState();
   667→                            }
   668→                        }
   669→                    }
   670→                    break;
   671→
   672→                case 'changeFa':
   673→                    if (currentTableId) {
   674→                        const table = tables.get(currentTableId);
   675→                        if (table && table.getCurrentPlayerId() === playerId) {
   676→                            const result = table.changeFa(playerId);
   677→                            if (result) {
   678→                                table.broadcastMessage(`${playerName} 换了一张"發"`);
   679→                                table.broadcastGameState();
   680→                            }
   681→                        }
   682→                    }
   683→                    break;
   684→
   685→                case 'gang':
   686→                    if (currentTableId) {
   687→                        const table = tables.get(currentTableId);
   688→                        if (table && table.getCurrentPlayerId() === playerId) {
   689→                            const result = table.doGang(playerId, msg.cardId);
   690→                            if (result) {
   691→                                table.broadcastMessage(`${playerName} 暗杠！`);
   692→                                table.broadcastGameState();
   693→                            }
   694→                        }
   695→                    }
   696→                    break;
   697→
   698→                case 'draw':
   699→                    if (currentTableId) {
   700→                        const table = tables.get(currentTableId);
   701→                        if (table && table.getCurrentPlayerId() === playerId) {
   702→                            const card = table.drawCard(playerId);
   703→                            if (card) {
   704→                                table.broadcastGameState();
   705→                            } else {
   706→                                table.broadcastMessage('牌堆已空，流局！');
   707→                            }
   708→                        }
   709→                    }
   710→                    break;
   711→
   712→                case 'chat':
   713→                    if (currentTableId) {
   714→                        const table = tables.get(currentTableId);
   715→                        if (table) {
   716→                            table.broadcastMessage(`${playerName}: ${msg.text}`);
   717→                        }
   718→                    }
   719→                    break;
   720→            }
   721→        } catch (e) {
   722→            console.error('消息处理错误:', e);
   723→        }
   724→    });
   725→
   726→    ws.on('close', () => {
   727→        console.log('客户端断开:', playerName);
   728→
   729→        if (currentTableId && playerId) {
   730→            const table = tables.get(currentTableId);
   731→            if (table) {
   732→                // 游戏进行中不删除玩家，只标记断开
   733→                const player = table.players.get(playerId);
   734→                if (player) {
   735→                    player.ws = null;
   736→                    player.ready = false;
   737→                }
   738→
   739→                // 如果游戏未开始且房间为空，删除房间
   740→                if (!table.gameState.started && table.removePlayer(playerId)) {
   741→                    tables.delete(currentTableId);
   742→                    console.log(`牌桌 ${currentTableId} 已删除`);
   743→                }
   744→
   745→                table.broadcastPlayerList();
   746→            }
   747→            playerToTable.delete(playerId);
   748→        }
   749→    });
   750→});
   751→
   752→// 发送牌桌列表
   753→function sendTableList(ws) {
   754→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
   755→    ws.send(JSON.stringify({
   756→        type: 'tableList',
   757→        tables: tableList
   758→    }));
   759→}
   760→
   761→// 创建牌桌
   762→function createTable() {
   763→    tableCounter++;
   764→    const tableId = `table_${tableCounter}`;
   765→    const table = new GameTable(tableId, tableCounter);
   766→    tables.set(tableId, table);
   767→    console.log(`创建新牌桌: ${tableId}`);
   768→    return table;
   769→}
   770→
   771→// 加入牌桌
   772→function joinTable(ws, playerId, playerName, tableId, seatNum) {
   773→    const table = tables.get(tableId);
   774→    if (!table) {
   775→        ws.send(JSON.stringify({ type: 'error', message: '牌桌不存在' }));
   776→        return false;
   777→    }
   778→
   779→    if (table.addPlayer(ws, playerId, playerName, seatNum)) {
   780→        playerToTable.set(playerId, tableId);
   781→        table.broadcastPlayerList();
   782→        console.log(`${playerName} 加入牌桌 ${tableId}`);
   783→        return true;
   784→    } else {
   785→        ws.send(JSON.stringify({ type: 'error', message: '无法加入牌桌（已满或游戏已开始）' }));
   786→        return false;
   787→    }
   788→}
   789→
   790→// 获取本机IP
   791→function getLocalIP() {
   792→    const os = require('os');
   793→    const interfaces = os.networkInterfaces();
   794→
   795→    for (const name of Object.keys(interfaces)) {
   796→        for (const iface of interfaces[name]) {
   797→            if (iface.family === 'IPv4' && !iface.internal) {
   798→                return iface.address;
   799→            }
   800→        }
   801→    }
   802→    return 'localhost';
   803→}
   804→
   805→// 启动服务器
   806→server.listen(PORT, () => {
   807→    const localIP = getLocalIP();
   808→    console.log('');
   809→    console.log('Majiang Server Started!');
   810→    console.log(`Game URL: http://localhost:${PORT}`);
   811→    console.log(`LAN URL: http://${localIP}:${PORT}`);
   812→    console.log('');
   813→});
   814→
   815→// 定时清理空桌子（每5分钟检查一次）
   816→setInterval(() => {
   817→    for (const [tableId, table] of tables) {
   818→        // 如果桌子没有玩家，或者所有玩家都已断开连接
   819→        if (table.players.size === 0) {
   820→            tables.delete(tableId);
   821→            console.log(`Cleaned up empty table: ${tableId}`);
   822→        } else {
   823→            // 检查是否所有玩家都已断开
   824→            let allDisconnected = true;
   825→            for (const player of table.players.values()) {
   826→                if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   827→                    allDisconnected = false;
