   831→            if (allDisconnected && !table.gameState.started) {
   832→                tables.delete(tableId);
   833→                console.log(`Cleaned up disconnected table: ${tableId}`);
   834→            }
   835→        }
   836→    }
   837→}, 300000); // 5分钟
   838→
   839→// 导出
