file.content:
.showed-card.fa {
    background: #FFD700;
}

.showed-card.gang {
    background: #90EE90;
}

/* 手牌 */
.hand-area {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 2px;
    padding: 10px;
    background: rgba(0,0,0,0.3);
    border-radius: 10px;
    max-width: 100%;
}

.card {
    width: 45px;
    height: 65px;
    background: linear-gradient(180deg, #fff 0%, #f0f0f0 100%);
    border-radius: 5px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s;
    box-shadow: 0 2px 5px rgba(0,0,0,0.3);
    position: relative;
}

.card:hover {
    transform: translateY(-5px);
    box-shadow: 0 5px 15px rgba(0,0,0,0.4);
}

.card.selected {
    transform: translateY(-15px);
    box-shadow: 0 10px 20px rgba(0,0,0,0.5);
}

.card.dragging {
    opacity: 0.5;
    transform: scale(1.1);
}

.card.drag-over {
    border-left: 3px solid #FFD700;
}

.card.wild {
    border: 2px solid #FFD700;
    background: linear-gradient(180deg, #FFFDE7 0%, #FFF9C4 100%);
}

.card-rank {
    font-size: 18px;
    font-weight: bold;
}

.card-suit {
    font-size: 12px;
    color: #666;
}

.card.tong .card-rank { color: #2196F3; }
.card.tiao .card-rank { color: #4CAF50; }
.card.wan .card-rank { color: #f44336; }
.card.feng .card-rank { color: #333; }
.card.jian .card-rank { color: #333; }

.card.zhong { background: linear-gradient(180deg, #FFCDD2 0%, #EF9A9A 100%); }
.card.fa { background: linear-gradient(180deg, #C8E6C9 0%, #A5D6A7 100%); }
.card.bai { background: linear-gradient(180deg, #fff 0%, #e0e0e0 100%); }

/* 中央信息区 */
.center-info {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    background: rgba(0,0,0,0.6);
    padding: 20px;
    border-radius: 10px;
}

.wild-card-info {
    margin-bottom: 15px;
}

.wild-card-info .label {
    font-size: 14px;
    color: #ccc;
}

.wild-card-info .card-display {
    font-size: 24px;
    font-weight: bold;
    color: #FFD700;
}

.deck-count {
    font-size: 14px;
    color: #ccc;
}

.game-time {
    font-size: 14px;
    color: #FFD700;
    margin-top: 5px;
}

/* 操作按钮 */
.action-buttons {
    display: flex;
    gap: 10px;
    justify-content: center;
    margin-top: 10px;
    flex-wrap: wrap;
}

.action-btn {
    padding: 8px 20px;
    font-size: 14px;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    transition: all 0.3s;
}

.action-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.action-btn.play {
    background: #4CAF50;
    color: white;
}

.action-btn.fa {
    background: #FFD700;
    color: #333;
}

.action-btn.gang {
    background: #9C27B0;
    color: white;
}

.action-btn.hu {
    background: #f44336;
    color: white;
}

/* 聊天区域 */
.chat-area {
    position: absolute;
    bottom: 200px;
    right: 10px;
    width: 200px;
    background: rgba(0,0,0,0.5);
    border-radius: 10px;
    padding: 10px;
}

.chat-messages {
    height: 150px;
    overflow-y: auto;
    font-size: 12px;
    margin-bottom: 10px;
}

.chat-input {
    display: flex;
    gap: 5px;
}

.chat-input input {
    flex: 1;
    padding: 5px;
    border: none;
    border-radius: 3px;
}

/* 准备界面 */
.ready-panel {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: rgba(0,0,0,0.8);
    padding: 30px;
    border-radius: 10px;
    text-align: center;

