broadcastGameState() {
    const playerIds = this.getSortedPlayerIds();

    for (const [playerId, player] of this.players) {
        if (!player.ws || player.ws.readyState !== WebSocket.OPEN) continue;

        const state = this.getPlayerGameState(playerId);
