    const currentPlayerSeat = this.players.get(currentPid)?.seatNum || 1;

    // 获取庄家的座位号
    const dealerPid = playerIds[this.gameState.dealer];
    const dealerSeat = this.players.get(dealerPid)?.seatNum || 1;

